  const params = new URLSearchParams(raw.slice(q + 1));
  const lang = params.get('lang') || 'glsl';
  if (lang !== 'glsl') throw new Error('unsupported lang=' + lang + ' (seed is GL2-only)');
  const b64 = params.get('src');
  if (!b64) throw new Error('href is missing src=');
  return decompress(b64);
